//! @file
//! Task T4 of
//! docs/superpowers/plans/2026-09-30-fermion-longrange-hamiltonian.md: the
//! existing fermion paths on unit cells with dimension-1 virtual legs and
//! vacancies (design section 7 of
//! docs/superpowers/specs/2026-09-30-fermion-longrange-hamiltonian-design.md).
//! Behaviour contract: "振る舞い契約書(T4)" of the plan.
//!
//! The cells are the honeycomb and kagome embeddings of tool/tenes_simple.py
//! (HoneycombLattice, KagomeLattice): a honeycomb site has one D = 1 leg (A
//! top, B bottom), a kagome B / C site two, and the kagome vacancy has
//! physical dimension 1 and four D = 1 legs. D = 1 legs and the vacancy's
//! physical leg carry the ledger [even]. Cells: honeycomb 2x4 (4x4, skew 0),
//! honeycomb 2x2 (4x2, skew 2), kagome 2x2 (4x4), and that kagome with
//! Hubbard sites.
//!
//! Where the numbers come from (test/fermion/gen_unit_d1.py, which writes the
//! GENERATED block below; see its docstring):
//!   - the gate chains are tenes_std's output (tenes_std.Model of a std.toml
//!     of the cell written by the generator, then make_evolution);
//!   - every reference value is a Fock-space construction of an open patch
//!     (a sparse generalisation of fock_oracle.py, checked against it on
//!     patches with D = 1 legs, a vacancy and dangling labels), with the
//!     long-range operator O_st and exp(-tau H) built there from creation /
//!     annihilation operators. Neither tenes_std's sign formula, nor the
//!     simple update, nor any measurement kernel enters a reference.
//!
//! Test cases (contract items in brackets; each item is its own case, so
//! that one red item does not hide the others, item 6):
//!   [truth] T4-0-self, T4-0-calibration: coverage of the cases; the patch
//!           contraction of the tensors before any update (and of the
//!           measurement windows) against the oracle. They pin the test's
//!           own tensor setup and patch convention, so that the other cases
//!           can only fail through the solver.
//!   T4-1  [1] one nearest-neighbour gate next to D = 1 legs through
//!         iTPS::simple_update, against O_st psi on the patch (the method of
//!         T2 contract item 1: six bra overlaps up to one scalar).
//!   T4-2a [2] tenes_std's gate chains of the honeycomb NNN (two hops along
//!         D > 1 bonds, also three hops around the D = 1 bond and across the
//!         skewed boundary) and the kagome NN (-1, 1) (through A, the
//!         vacancy in the patch), the same way; T4-2b complex, T4-2c
//!         Hubbard.
//!   T4-3a [3] measure_twosite() with the CTM environment (CHI = 1, every
//!         edge diagonal in its (ket, bra) pair with fixed weights, so the
//!         window is closed exactly), NN windows and long-range windows whose
//!         x_first relay crosses D = 1 bonds and vacancies, against the
//!         oracle's <c+_s c_t>, relative error 1e-10.
//!   T4-3b [3] the same with the mean-field environment (lambda).
//!   T4-4a/b [4] measure_correlation() (CTM / mean field): chains along x
//!         and y through D = 1 legs and vacancies, against the oracle.
//!   T4-5  [5] save / load of the kagome cell: Tn, ledgers (D = 1 legs,
//!         vacancy), lambda and the one-site values survive.
//! Cases tagged [mpi2] are registered a second time at two ranks.

