// ---- generated data layout -------------------------------------------------

//! One nonzero element (in1, in2, out1, out2) of a gate.
struct u1_entry {
  int i[4];
  double re;
  double im;
};

//! One gate of a chain: the bond it acts on, its shape, the ledgers of its
//! legs (in1, in2, out1, out2) from the rule of design section 6.1, and its
//! nonzero elements.
struct u1_gate_data {
  int source_site;
  int source_leg;
  int dims[4];
  std::array<const char*, 4> legs;
  const u1_entry* entries;
  std::size_t nentries;
};

//! A unit cell: kinds (0 = spinless d = 2 [e, o], 1 = Hubbard d = 4
//! [e, o, o, e], 2 = vacancy d = 1 [e]) and the embedding virtual dims
//! (l, t, r, b) of tenes_simple (D = 2, or 1).
struct u1_cell_data {
  const char* name;
  int lx;
  int ly;
  int skew;
  std::vector<int> kinds;
  std::vector<std::array<int, 4>> vdims;
};

//! Contract items 1 and 2: one Hamiltonian bond (source, dx, dy) of a cell,
//! its chain, the virtual dims of the run (the path bonds widened so that
//! nothing is truncated), and the reference overlaps of the patch (nrow x
//! ncol, raster from the top row; psites the unit-cell site of each
//! position, ppos the position of each site of the path).
struct u1_su_case {
  const char* name;
  int cell;
  int source;
  int dx;
  int dy;
  bool is_complex;
  int seed;
  std::vector<std::array<int, 4>> vdims;
  std::vector<u1_gate_data> gates;
  int nrow;
  int ncol;
  std::vector<int> psites;
  std::vector<int> ppos;
  std::vector<std::array<double, 2>> before;
  std::vector<std::array<double, 2>> after;
};

//! Contract item 3: <c+_s c_t> of the window (source, dx, dy) with the CTM
//! and the mean-field environment, each with a scale that does not cancel;
//! how many D = 1 bonds and vacancies the x_first relay path crosses; and
//! the overlaps of the window's state (perimeter at label 0) with the bras.
struct u1_pair_value {
  int source;
  int dx;
  int dy;
  double ctm;
  double ctm_scale;
  double mf;
  double mf_scale;
  int d1_crossed;
  int vacancies_crossed;
  std::vector<double> overlaps;
};

//! Contract item 4: <A_left B_right> of the row (left, dx, dy, A, B) of
//! measure_correlation(), A / B = 0 (c+) or 1 (c).
struct u1_corr_value {
  int left;
  int dx;
  int dy;
  int lop;
  int rop;
  double ctm;
  double ctm_scale;
  double mf;
  double mf_scale;
};

struct u1_measure_set {
  int cell;
  std::vector<u1_pair_value> pairs;
  std::vector<u1_corr_value> corrs;
};

